using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task GreetingScenario_ReturnsCoherentResponse()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(responseText),
            "Chat agent should return a non-empty response.");

        // Evaluate coherence using AI-based evaluator
        var evaluators = new IEvaluator[] { new CoherenceEvaluator() };
        var chatTurn = new ChatTurn(messages, response.Messages);
        var results = await EvaluateAsync(chatClient, evaluators, chatTurn);

        AssertPassingScore(results, nameof(CoherenceEvaluator), threshold: 3.0f);
    }

    [TestMethod]
    public async Task FactualQuestion_ReturnsRelevantResponse()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(responseText),
            "Chat agent should return a non-empty response.");

        var evaluators = new IEvaluator[] { new RelevanceEvaluator(), new CoherenceEvaluator() };
        var chatTurn = new ChatTurn(messages, response.Messages);
        var results = await EvaluateAsync(chatClient, evaluators, chatTurn);

        AssertPassingScore(results, nameof(RelevanceEvaluator), threshold: 3.0f);
        AssertPassingScore(results, nameof(CoherenceEvaluator), threshold: 3.0f);
    }

    private static async Task<EvaluationResult> EvaluateAsync(
        IChatClient chatClient,
        IEnumerable<IEvaluator> evaluators,
        ChatTurn chatTurn)
    {
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            await evaluator.EvaluateAsync(chatTurn, result, chatClient);
        }
        return result;
    }

    private static void AssertPassingScore(
        EvaluationResult result,
        string evaluatorName,
        float threshold)
    {
        var metric = result.Metrics.Values
            .FirstOrDefault(m => m.Identifier.Contains(evaluatorName, StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(metric, $"Expected metric from {evaluatorName} to be present.");

        if (metric is NumericMetric numericMetric)
        {
            Assert.IsTrue(
                numericMetric.Value >= threshold,
                $"{evaluatorName} score {numericMetric.Value} is below threshold {threshold}.");
        }
    }
}

